<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLLabelAttributes } from 'svelte/elements'; import { getSelectContext } from './select-context.svelte.js'; export interface Props extends Omit<HTMLLabelAttributes, 'children'> { children?: Snippet; ref?: HTMLLabelElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const select = getSelectContext();</script>
<label bind:this={ref} {...rest} id={select.labelId} for={select.triggerId}>{@render children?.()}</label>
